(r, big) => {
    const n = big ? 100000 : r.int(1, 12);
    const q = Math.floor(n / 4);
    if (n < 4) { const v = r.int(0, 9); return [new Array(n).fill(v)]; }
    const counts = [r.int(q + 1, big ? q + 10 : n)];
    let left = n - counts[0];
    while (left > 0) { const c = r.int(1, Math.min(left, big ? 1 : q)); counts.push(c); left -= c; }
    const shuffled = r.shuffle(counts);
    const vals = r.distinct(shuffled.length, 0, 100000).sort((a, b) => a - b);
    const arr = [];
    shuffled.forEach((c, i) => { for (let k = 0; k < c; k++) arr.push(vals[i]); });
    return [arr];
  }

