function quarterPlusValue(arr: number[]): number {
  const n = arr.length;
  // first index whose value is >= v (strict = false) or > v (strict = true)
  const bound = (v: number, strict: boolean) => {
    let lo = 0, hi = n;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (arr[mid] < v || (strict && arr[mid] === v)) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  };
  for (const c of [Math.floor(n / 4), Math.floor(n / 2), Math.floor((3 * n) / 4)]) {
    const v = arr[c];
    if (4 * (bound(v, true) - bound(v, false)) > n) return v;
  }
  return -1;
}

